void ConfigureMiddlewares()
{
    app.UseExceptionHandler("/error");
    app.UseQuickCodeForwardedHeaders();

    app.ConfigureSitePipelineEarly(app.Environment);

	if (!app.Environment.IsDevelopment())
	{
    	app.UseHsts();
	}
    
    app.UseGatewaySecurityHeaders(); 
    app.UseRateLimiting();
    app.UseInputValidation();
    app.UseSecurityLogging();
    app.UseSecurityAudit();
    app.UsePasswordPolicy();
    
    app.UseSwagger();
    app.UseSwaggerUI();

    if (app.Configuration.GetValue<bool>("AppSettings:UseHealthCheck"))
    {
        app.UseHealthChecks("/hc", new HealthCheckOptions
        {
            Predicate = _ => true,
            ResponseWriter = UIResponseWriter.WriteHealthCheckUIResponse
        });

        app.UseHealthChecksUI(config => { config.UIPath = "/hc-ui"; });
    }

    app.UseHttpsRedirection();
    app.UseAuthentication();
    app.UseAuthorization();

    app.UseQuickCodeCors(app.Configuration);

    app.ConfigureSitePipeline(app.Environment);

    var gatewayGroup = app.MapGroup("/api/gateway").WithTags("Gateway");
    
    app.MapGet("/", GetServicesHtml).WithTags("Dashboard");

    app.Map("/error", (HttpContext context) =>
    {
        var exception = context.Features.Get<IExceptionHandlerFeature>()?.Error;
        if (exception != null)
        {
            GatewayLoggingHelper.LogDependencyError("UnhandledException", exception, context.Request.Path, context.Request.Method);
        }

        var isDev = app.Environment.IsDevelopment();

        return Results.Problem(
            title: "Unexpected error Gateway",
            detail: isDev ? exception?.Message : "Something went wrong.",
            statusCode: 500
        );
    }).ExcludeFromDescription();

    gatewayGroup.MapGet("/reset", () =>
    {
        if (InMemoryConfigProvider.IsClustersUpdatedFromConfig == 1)
        {
            InMemoryConfigProvider.IsClustersUpdatedFromConfig = -1;
        }
    });

    gatewayGroup.MapGet("/config", () => InMemoryConfigProvider.proxyConfig.ReverseProxy.ToJson());

    gatewayGroup.MapGet("/swagger-config", () => InMemoryConfigProvider.swaggerMaps.ToJson());

    gatewayGroup.MapPost("/service-token", (HttpContext context, GatewayServiceTokenIssueRequest request, IGatewayServiceTokenGenerator tokenGenerator) =>
    {
        if (!IsInternalTokenRequestAuthorized(context))
        {
            return Results.Unauthorized();
        }

        if (string.IsNullOrWhiteSpace(request.TargetModuleName))
        {
            return Results.BadRequest(new { message = "targetModuleName is required" });
        }

        if (!IsModuleAllowedForInternalToken(request.TargetModuleName))
        {
            Log.Warning("Internal service-token request denied for module {Module}: not in the allowed module list", request.TargetModuleName);
            return Results.Forbid();
        }

        // Internal system-to-system token: identity/claims are fixed by the Gateway and any
        // caller-supplied claims are ignored so a compromised internal caller cannot impersonate a user.
        var token = tokenGenerator.Create(
            request.TargetModuleName,
            userId: "gateway-internal",
            permissionGroup: "InternalService");

        return Results.Ok(new GatewayServiceTokenIssueResponse { Token = token });
    });

    InMemoryConfigProvider.app = app;
  
    app.MapReverseProxy(proxyPipeline =>
    {
        proxyPipeline.Use(YarpMiddlewareKafkaManager(app.Services));
        proxyPipeline.Use(YarpMiddlewareApiAuthorization(app.Services));
    });

    app.ConfigureSitePipelineLate(app.Environment);
}

void ConfigureEnvironmentVariables(IConfiguration configuration)
{
    configuration.UpdateConfigurationFromEnv();

    builder.Services.AddAuthorizationBuilder()
        .AddPolicy("QuickCodeGatewayPolicy", policy =>
        {
            policy.RequireAssertion(context =>
            {
                var httpContext = context.Resource as HttpContext;
                if (httpContext == null)
                {
                    return false;
                }

                var token = httpContext.Request.Headers["Authorization"].FirstOrDefault()?.Split(" ").Last();
                if (!string.IsNullOrEmpty(token) && token.IsTokenExpired()) 
                {
                    httpContext.Response.Headers.Append("Token-Expired", "true");
                }

                return true;
            });
        });

    Console.WriteLine($"environmentName : {environmentName}");
    Log.Information("Gateway environment: {EnvironmentName}", environmentName);
}


Func<HttpContext, Func<Task>, Task> YarpMiddlewareKafkaManager(IServiceProvider services)
{
    return async (context, next) =>
    {
        try
        {
            var memoryCache = services.GetRequiredService<IMemoryCache>();
            var kafkaProducer = services.GetRequiredService<IKafkaProducerWrapper>();
            var originalBodyStream = context.Response.Body;
            context.Request.EnableBuffering();

            using var responseBody = new MemoryStream();
            context.Response.Body = responseBody;

            var stopwatch = Stopwatch.StartNew();
            try
            {
                await next();
                _ = Task.Run(async () =>
                {
                    try
                    {
                        await KafkaHelper.SendKafkaMessageIfEventExists(services, memoryCache, kafkaProducer, context, stopwatch);
                    }
                    catch (Exception ex)
                    {
                        GatewayLoggingHelper.LogDependencyError("BackgroundKafkaPublish", ex, context.Request.Path, context.Request.Method);
                    }
                });
            }
            catch (Exception ex)
            {
                var kafkaEvent = await KafkaHelper.CheckKafkaEventExists(services, memoryCache, context);
                if (kafkaEvent is not null)
                {
                    _ = Task.Run(async () =>
                    {
                        try
                        {
                            await KafkaHelper.SendErrorKafkaMessage(kafkaProducer, kafkaEvent.TopicName, context, stopwatch, ex);
                        }
                        catch (Exception sendEx)
                        {
                            GatewayLoggingHelper.LogKafkaFailure("background-error-publish", sendEx, kafkaEvent.TopicName);
                        }
                    });
                }

                Log.Error(ex, "Gateway request pipeline failed for {Method} {Path}", context.Request.Method, context.Request.Path);
                throw;
            }
            finally
            {
                responseBody.Seek(0, SeekOrigin.Begin);
                await responseBody.CopyToAsync(originalBodyStream);
                stopwatch.Stop();
            }
        }
        catch (Exception ex)
        {
            Log.Error(ex, "Gateway Kafka middleware failed for {Path}", context.Request.Path);
            throw;
        }
    };
}

Func<HttpContext, Func<Task>, Task> YarpMiddlewareApiAuthorization(IServiceProvider services)
{
    return async (context, next) =>
    {
        try
        {
            var path = context.Request.Path.Value ?? string.Empty;

            if (IsPublicAuthPath(path))
            {
                await next();
                return;
            }

            var memoryCache = services.GetRequiredService<IMemoryCache>();
            var token = ExtractToken(context);
            var cacheKey = $"AuthJwtTokens-{token}";
        
            if (string.IsNullOrEmpty(token))
            {
                context.Response.StatusCode = StatusCodes.Status401Unauthorized;
                await context.Response.WriteAsync("Authorization required");
                return;
            }
        
            if (token.IsTokenExpired())
            {
                memoryCache.Remove(cacheKey);
                await HandleExpiredToken(context);
                return;
            }

            if (!await ValidateAndProcessToken(context, services, token, cacheKey))
            {
                return;
            }

            await next();
        }
        catch (QuickCodeSwaggerException ex)
        {
            GatewayLoggingHelper.LogDependencyError("ApiAuthorization", ex, context.Request.Path, context.Request.Method);
            context.Response.StatusCode = ex.StatusCode is >= 400 and < 600 ? ex.StatusCode : StatusCodes.Status502BadGateway;
            context.Response.ContentType = "application/json";
            await context.Response.WriteAsync(JsonConvert.SerializeObject(new
            {
                message = "Gateway authorization dependency failed",
                statusCode = ex.StatusCode,
                response = ex.Response
            }));
        }
        catch (Exception ex)
        {
            GatewayLoggingHelper.LogDependencyError("ApiAuthorization", ex, context.Request.Path, context.Request.Method);
            throw;
        }
    };
}



string ExtractToken(HttpContext context)
{
    return context.Request.Headers.Authorization.FirstOrDefault()?.Split(" ").Last() ?? string.Empty;
}

static bool IsPublicAuthPath(string path) =>
    path.StartsWith("/api/auth/login", StringComparison.OrdinalIgnoreCase)
    || path.StartsWith("/api/auth/register", StringComparison.OrdinalIgnoreCase)
    || path.StartsWith("/api/auth/refresh", StringComparison.OrdinalIgnoreCase)
    || path.StartsWith("/api/auth/logout", StringComparison.OrdinalIgnoreCase)
    || path.StartsWith("/swagger", StringComparison.OrdinalIgnoreCase);

async Task HandleExpiredToken(HttpContext context)
{
    context.Response.Headers.Append("Token-Expired", "true");
    context.Response.StatusCode = StatusCodes.Status401Unauthorized;
    await context.Response.WriteAsync("Token expired");
}

async Task<bool> ValidateAndProcessToken(HttpContext context, IServiceProvider services, string token, string cacheKey)
{
    var memoryCache = services.GetRequiredService<IMemoryCache>();

    bool isValidToken;
    try
    {
        isValidToken = await ValidateToken(services, token, cacheKey, memoryCache);
    }
    catch (Exception ex)
    {
        GatewayLoggingHelper.LogDependencyError("ValidateToken", ex, context.Request.Path, context.Request.Method);
        throw;
    }

    if (!isValidToken)
    {
        Log.Warning("Gateway rejected invalid token for {Method} {Path}", context.Request.Method, context.Request.Path);
        await HandleInvalidToken(context);
        return false;
    }

    var jwtClaims = token.ParseJwtPayload();
    var permissionGroupName = jwtClaims["PermissionGroupName"];

    bool isMethodValid;
    try
    {
        isMethodValid = await IsMethodValid(context, services, permissionGroupName, memoryCache);
    }
    catch (Exception ex)
    {
        GatewayLoggingHelper.LogDependencyError("ValidateMethodAccess", ex, context.Request.Path, context.Request.Method);
        throw;
    }

    if (!isMethodValid)
    {
        Log.Warning(
            "Gateway rejected method access. Method={Method} Path={Path} PermissionGroup={PermissionGroup}",
            context.Request.Method,
            context.Request.Path,
            permissionGroupName);
        await HandleInvalidMethod(context);
        return false;
    }

    ReplaceAuthorizationWithServiceToken(context, services, jwtClaims);
    EnsureForwardedUserAgent(context);

    return true;
}

void ReplaceAuthorizationWithServiceToken(HttpContext context, IServiceProvider services, Dictionary<string, string> jwtClaims)
{
    var endpoint = context.GetEndpoint();
    if (endpoint?.DisplayName is null)
    {
        Log.Warning("Gateway service token skipped: endpoint DisplayName missing for {Method} {Path}",
            context.Request.Method, context.Request.Path);
        return;
    }

    var moduleName = endpoint.DisplayName.KebabCaseToPascal("");
    var tokenGenerator = services.GetRequiredService<IGatewayServiceTokenGenerator>();
    jwtClaims.TryGetValue(JwtRegisteredClaimNames.Sub, out var userId);
    jwtClaims.TryGetValue(JwtRegisteredClaimNames.Email, out var userEmail);
    jwtClaims.TryGetValue("PermissionGroupName", out var permissionGroup);

    var serviceToken = tokenGenerator.Create(moduleName, userId, permissionGroup, userEmail);

    if (context.Request.Headers.TryGetValue("Authorization", out var originalAuthorization)
        && !StringValues.IsNullOrEmpty(originalAuthorization))
    {
        context.Request.Headers["X-Forwarded-Authorization"] = originalAuthorization.ToString();
    }

    context.Request.Headers.Authorization = $"Bearer {serviceToken}";
}

async Task<bool> ValidateToken(IServiceProvider services, string token, string cacheKey, IMemoryCache memoryCache)
{
    return !token.IsTokenExpired() && await memoryCache.GetOrAddAsync<bool>(cacheKey,
        async parameters => await KafkaHelper.GetTokenIsValid(services, token),
        TimeSpan.FromSeconds(token.GetTokenExpirationTime()));
}

async Task HandleInvalidToken(HttpContext context)
{
    context.Response.StatusCode = StatusCodes.Status401Unauthorized;
    await context.Response.WriteAsync("Token is invalid");
}

async Task<bool> IsMethodValid(HttpContext context, IServiceProvider services, string permissionGroupName, IMemoryCache memoryCache)
{
    if (string.Equals(permissionGroupName, "Admin", StringComparison.OrdinalIgnoreCase))
    {
        return true;
    }

    var groupMethods = await GetGroupMethods(services, memoryCache);
    var path = context.Request.Path.Value!;
    var validPaths = groupMethods
        .Where(i => string.Equals(i.PermissionGroupName, permissionGroupName, StringComparison.OrdinalIgnoreCase)
                    && i.HttpMethod.ToString().Equals(context.Request.Method, StringComparison.OrdinalIgnoreCase))
        .Select(i => i.Path)
        .ToList();

    return path.IsRouteMatch(validPaths) || path.StartsWith("/api/auth/login", StringComparison.OrdinalIgnoreCase);
}


async Task<List<GroupHttpMethodPath>> GetGroupMethods(IServiceProvider services, IMemoryCache memoryCache)
{
    var configuration = services.GetRequiredService<IConfiguration>();
    var apiMethodAccessGrantsClient = services.GetRequiredService<IApiMethodAccessGrantsClient>();
    var apiMethodDefinitionsClient = services.GetRequiredService<IApiMethodDefinitionsClient>();
    var tokenGenerator = services.GetRequiredService<IGatewayServiceTokenGenerator>();

    return await memoryCache.GetOrAddAsync<List<GroupHttpMethodPath>>("GroupMethods",
        async parameters => await GetAllGroupMethods(configuration, apiMethodAccessGrantsClient, apiMethodDefinitionsClient, tokenGenerator),
        TimeSpan.FromMinutes(1));
}

async Task HandleInvalidMethod(HttpContext context)
{
    context.Response.StatusCode = StatusCodes.Status403Forbidden;
    context.Response.ContentType = "application/json";
    await context.Response.WriteAsync(JsonConvert.SerializeObject(new { message = "Method Is Not Valid" }));
}

void EnsureForwardedUserAgent(HttpContext context)
{
    if (context.Request.Headers.TryGetValue("X-Forwarded-User-Agent", out var forwardedUserAgent)
        && !StringValues.IsNullOrEmpty(forwardedUserAgent))
    {
        return;
    }

    if (context.Request.Headers.TryGetValue("User-Agent", out var userAgent) && !StringValues.IsNullOrEmpty(userAgent))
    {
        context.Request.Headers["X-Forwarded-User-Agent"] = userAgent;
    }
}

/// <summary>Pascal/camel project segment → spaced title for Gateway HTML (e.g. DemoLocal → Demo Local).</summary>
static string FormatGatewayProjectDisplayName(string projectSegment)
{
    if (string.IsNullOrWhiteSpace(projectSegment))
        return projectSegment;
    const string pattern = @"[A-Z][a-z]*|[a-z]+|\d+";
    var matches = System.Text.RegularExpressions.Regex.Matches(projectSegment, pattern);
    return string.Join(" ", matches.Select(m => m.Value));
}

IResult GetServicesHtml(HttpContext context)
{
    var portalUrlConfig = app.Configuration.GetSection("AppSettings:PortalUrl").Get<string>();
    var elasticUrl = app.Configuration.GetSection("AppSettings:ElasticUrl").Get<string>();
    var kafdropUrl = app.Configuration.GetSection("AppSettings:KafdropUrl").Get<string>();
    var eventListenerUrlConfig =  app.Configuration.GetSection("AppSettings:EventListenerUrl").Get<string>();
    const string swaggerJson = "/v1/swagger.json";
    const string swaggerHtml = "/index.html";
    
    const string quickcodeBaseUrl = ".quickcode.net";
    const string cloudRunBaseUrl = "-821209474183.europe-west1.run.app";

    var request = context.Request;


    var scheme = request.Scheme;  
    var host = request.Host.Value; 
    var path = request.Path;  
    var query = request.QueryString; 

    var displayUrl = $"{scheme}://{host}{path}{query}";
    
    var isRewriteUrl = displayUrl.Contains(quickcodeBaseUrl);
    var portalUrl = isRewriteUrl ? portalUrlConfig!.Replace(cloudRunBaseUrl, quickcodeBaseUrl) : portalUrlConfig!;
    var eventListenerUrl = isRewriteUrl
        ? eventListenerUrlConfig!.Replace(cloudRunBaseUrl, quickcodeBaseUrl)
		: eventListenerUrlConfig!;
    

    var destinations = InMemoryConfigProvider.swaggerMaps.Select(c => new
    {
        ClusterId = c.Key,
        Address = isRewriteUrl
            ? c.Value.Endpoint.Replace(swaggerJson, swaggerHtml).Replace(cloudRunBaseUrl, quickcodeBaseUrl)
            : c.Value.Endpoint.Replace(swaggerJson, swaggerHtml)
    }).ToList();
    
    destinations.Add(new { ClusterId = "Event Listener Service", Address = $"{eventListenerUrl}/swagger/index.html" }!);

    var tabsComboBoxHtml = destinations.Select((value, index) =>
        $"<li><a id=\"{value.ClusterId.ToLower().Replace(" ", "_")}\" data-toggle=\"tab\"  class=\"dropdown-item\" href=\"{value.Address}\">{value.ClusterId.KebabCaseToPascal()}</a></li>");

    var lastUpdate = DateTime.UtcNow - InMemoryConfigProvider.LastUpdateDateTime;
    var lastUpdateValue = $"{lastUpdate.TotalSeconds:0}s ago";
    if (lastUpdate.Minutes > 0)
    {
        lastUpdateValue = $"{lastUpdate.TotalMinutes:0}m {(lastUpdate.TotalSeconds % 60):0}s ago";
    }

    if (lastUpdate.Hours > 0)
    {
        lastUpdateValue = $"{lastUpdate.TotalHours:0}h {(lastUpdate.TotalMinutes % 60):0}m ago";
    }

    var projectName = typeof(ReverseProxyConfigModel).Namespace!.Split(".")[1];
    var fileContent = File.ReadAllText("Dashboard/Dashboard.html");
    var tabsContent = string.Join("<li><hr class=\"dropdown-divider\"></li>", tabsComboBoxHtml.ToArray());

    var githubUrl = $"https://github.com/QuickCodeNet/{projectName.ToLower()}";
    var isHttpsText = "<meta http-equiv=\"Content-Security-Policy\" content=\"upgrade-insecure-requests\">";
    
    if (environmentName == "Local")
    {
        isHttpsText = "";
    }
    
    isHttpsText = "";
    fileContent = fileContent.Replace("<!--|@TABS@|-->", string.Join("", tabsContent));
    fileContent = fileContent.Replace("<!--|@TABS_COUNT@|-->", destinations.Count().ToString());
    fileContent = fileContent.Replace("<!--|@LAST_UPDATE@|-->", lastUpdateValue);
    fileContent = fileContent.Replace("<!--|@ENVIRONMENT@|-->", environmentName);
    fileContent = fileContent.Replace("<!--|@PROJECT_NAME@|-->", FormatGatewayProjectDisplayName(projectName));
    fileContent = fileContent.Replace("<!--|@PROJECT_NAME_LOWER@|-->", projectName.ToLower());
    fileContent = fileContent.Replace("<!--|@PORTAL_URL@|-->", portalUrl);
    fileContent = fileContent.Replace("<!--|@ELASTIC_URL@|-->", elasticUrl);
    fileContent = fileContent.Replace("<!--|@GITHUB_URL@|-->", githubUrl);
    fileContent = fileContent.Replace("<!--|@KAFDROP_URL@|-->", kafdropUrl);
    fileContent = fileContent.Replace("<!--|@EVENT_LISTENER_URL@|-->", eventListenerUrl);
    fileContent = fileContent.Replace("<!--|@VERSION@|-->", $"{Assembly.GetExecutingAssembly().GetName().Version}");
    fileContent = fileContent.Replace("<!--|@IS_HTTPS@|-->", isHttpsText);
    return Results.Extensions.Html(@$"{fileContent}");
}


async Task<List<GroupHttpMethodPath>> GetAllGroupMethods(
    IConfiguration configuration,
    IApiMethodAccessGrantsClient apiMethodAccessGrantsClient,
    IApiMethodDefinitionsClient apiMethodDefinitionsClient,
    IGatewayServiceTokenGenerator tokenGenerator)
{
    const string identityModuleName = "IdentityModule";

    try
    {
        SetServiceTokenToClients(apiMethodAccessGrantsClient, apiMethodDefinitionsClient,
            tokenGenerator.Create(identityModuleName));
        var authorizationsGroups = await apiMethodAccessGrantsClient.ApiMethodAccessGrantsListAsync();
        SetServiceTokenToClients(apiMethodAccessGrantsClient, apiMethodDefinitionsClient,
            tokenGenerator.Create(identityModuleName));
        var authorizations = await apiMethodDefinitionsClient.ApiMethodDefinitionsListAsync();

        SetServiceTokenToClients(apiMethodAccessGrantsClient, apiMethodDefinitionsClient, string.Empty);
        var authorizationsGroupsActive = authorizationsGroups.Where(i => i.IsActive);

        var allMethods = from authGroup in authorizationsGroupsActive
            join a in authorizations on authGroup.ApiMethodDefinitionKey equals a.Key
            select new GroupHttpMethodPath()
            {
                PermissionGroupName = authGroup.PermissionGroupName, HttpMethod = a.HttpMethod, Path = a.UrlPath
            };

        Log.Debug("Gateway loaded {MethodCount} API method definitions for authorization", allMethods.Count());
        return allMethods.ToList();
    }
    catch (Exception ex)
    {
        GatewayLoggingHelper.LogDependencyError("GetAllGroupMethods", ex);
        throw;
    }
}

void SetServiceTokenToClients(
    IApiMethodAccessGrantsClient apiMethodAccessGrantsClient,
    IApiMethodDefinitionsClient apiMethodDefinitionsClient,
    string serviceToken)
{
    (apiMethodAccessGrantsClient as ClientBase)!.SetBearerToken(serviceToken);
    (apiMethodDefinitionsClient as ClientBase)!.SetBearerToken(serviceToken);
}

bool IsInternalTokenRequestAuthorized(HttpContext context)
{
    var configuredKey = ResolveGatewayInternalTokenKey();
    if (string.IsNullOrWhiteSpace(configuredKey))
    {
        Log.Warning("Gateway internal token key is missing; internal service-token request denied");
        return false;
    }

    if (!context.Request.Headers.TryGetValue(GatewayServiceTokenSettings.InternalTokenHeaderName, out var providedKey))
    {
        return false;
    }

    var provided = System.Text.Encoding.UTF8.GetBytes(providedKey.ToString());
    var expected = System.Text.Encoding.UTF8.GetBytes(configuredKey);
    return provided.Length == expected.Length
        && System.Security.Cryptography.CryptographicOperations.FixedTimeEquals(provided, expected);
}

static bool IsModuleAllowedForInternalToken(string moduleName)
{
    var allowed = Environment.GetEnvironmentVariable(GatewayServiceTokenSettings.InternalAllowedModulesEnvVar);

    // When no whitelist is configured, allow any module (single-tenant / local dev).
    if (string.IsNullOrWhiteSpace(allowed))
    {
        return true;
    }

    return allowed
        .Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
        .Any(m => string.Equals(m, moduleName, StringComparison.OrdinalIgnoreCase));
}

static string? ResolveGatewayInternalTokenKey()
{
    return Environment.GetEnvironmentVariable(GatewayServiceTokenSettings.InternalTokenKeyEnvVar)
           ?? Environment.GetEnvironmentVariable(GatewayServiceTokenSettings.QuickCodeInternalTokenKeyEnvVar);
}

